78	      int parallelism = Math.max(Math.min(markerPaths.size(), config.getRollbackParallelism()), 1);
79	      List<HoodieRollbackRequest> rollbackRequestList = context.map(markerPaths, markerFilePath -> {
80	        String typeStr = markerFilePath.substring(markerFilePath.lastIndexOf(".") + 1);
81	        IOType type = IOType.valueOf(typeStr);
82	        String filePathStr = WriteMarkers.stripMarkerSuffix(markerFilePath);
83	        StoragePath filePath = new StoragePath(basePath, filePathStr);
84	        String partitionPath = FSUtils.getRelativePartitionPath(new StoragePath(basePath), filePath.getParent());
85	        String fileId = FSUtils.getFileIdFromFilePath(filePath);
86	
87	        switch (type) {
88	          case MERGE:
89	          case CREATE:
90	            return createRollbackRequestForCreateAndMerge(fileId, partitionPath, filePath, instantToRollback);
91	          case APPEND:
92	            return createRollbackRequestForAppend(fileId, partitionPath, filePath, instantToRollback, filePathStr);
93	          default:
94	            throw new HoodieRollbackException("Unknown marker type, during rollback of " + instantToRollback);
95	        }
96	      }, parallelism);
97	      // The rollback requests for append only exist in table version 6 and below which require groupBy
98	      return table.version().greaterThanOrEquals(HoodieTableVersion.EIGHT)
99	          ? rollbackRequestList
100	          : RollbackUtils.groupRollbackRequestsBasedOnFileGroup(rollbackRequestList);
101	    } catch (Exception e) {
102	      throw new HoodieRollbackException("Error rolling back using marker files written for " + instantToRollback, e);
103	    }
104	  }
