                .setLatestBaseInstant(getLatestBaseInstant.apply(rollbackRequest))
                .setFilesToBeDeleted(getFilesToBeDeletedFunc.apply(rollbackRequest))
                .setLogBlocksToBeDeleted(Collections.emptyMap())
